-- Controlled, non-destructive contribution corrections.
alter table public.contributions add column correction_reason text;
create or replace function public.correct_contribution_status(target_contribution_id uuid,new_status public.giving_transaction_status,reason text) returns public.contributions language plpgsql security definer set search_path='' as $$ declare r public.contributions; begin if (select auth.uid()) is null then raise exception 'Authentication required'; end if; select * into r from public.contributions where id=target_contribution_id for update; if r.id is null or not private.has_church_role(r.church_id,array['owner','administrator','finance']::public.church_role[]) then raise exception 'Contribution not found or access denied'; end if; if r.status <> 'completed' or new_status not in ('refunded','voided') then raise exception 'Only completed contributions may be refunded or voided'; end if; if nullif(btrim(reason),'') is null then raise exception 'Correction reason is required'; end if; update public.contributions set status=new_status,correction_reason=btrim(reason) where id=r.id returning * into r; return r; end $$;
revoke all on function public.correct_contribution_status(uuid,public.giving_transaction_status,text) from public,anon; grant execute on function public.correct_contribution_status(uuid,public.giving_transaction_status,text) to authenticated;
revoke delete on public.contributions from authenticated;